sources.content:
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

data "aws_caller_identity" "current" {}

locals {
   name_prefix = var.environment
   account_id  = data.aws_caller_identity.current.account_id
}

# S3 bucket for data storage
resource "aws_s3_bucket" "data_bucket" {
  bucket = "${local.name_prefix}-${var.s3_bucket_name}-${var.aws_region}-${local.account_id}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "data_bucket_pab" {
  bucket = aws_s3_bucket.data_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Configure S3 bucket lifecycle policy
resource "aws_s3_bucket_lifecycle_configuration" "data_lifecycle" {
  bucket = aws_s3_bucket.data_bucket.id

  rule {
    id     = "delete-after-90-days"
    status = "Enabled"

    # Apply to ALL objects
    filter {}

    expiration {
      days = 90
    }

  }
}

# Encrypt S3 bucket using SSE-S3
resource "aws_s3_bucket_server_side_encryption_configuration" "data_encryption" {
  bucket = aws_s3_bucket.data_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"  # SSE-S3 encryption
    }
    bucket_key_enabled = true
  }
}

# Upload the script file to S3
resource "aws_s3_object" "file_upload" {
  bucket = aws_s3_bucket.data_bucket.id
  key    = "scripts/glue-zero-etl-script.py"
  source = "glue-zero-etl-script.py"
}

# DynamoDB source table
resource "aws_dynamodb_table" "source_table" {
  name             = "${var.table_name}"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "id"

  attribute {
    name = "id"
    type = "S"
  }

  point_in_time_recovery {
    enabled = true
  }
}

# IAM role for Glue Zero-ETL
resource "aws_iam_role" "glue_zero_etl_role" {
  name = "${local.name_prefix}-glue-zero-etl-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "glue_zero_etl_policy" {
  name = "${local.name_prefix}-glue-zero-etl-policy"
  role = aws_iam_role.glue_zero_etl_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:GetRecords",
          "dynamodb:ListStreams",
          "dynamodb:ExportTableToPointInTime",
          "dynamodb:Scan",
          "dynamodb:Query"
        ]
        Resource = [
          aws_dynamodb_table.source_table.arn,
          "${aws_dynamodb_table.source_table.arn}/stream/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.data_bucket.arn,
          "${aws_s3_bucket.data_bucket.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "glue:GetJob",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:StartJobRun",
          "glue:BatchStopJobRun",
          "glue:GetDatabase",
          "glue:GetDatabases",
          "glue:GetTable",
          "glue:GetTables",
          "glue:GetPartition",
          "glue:GetPartitions",
          "glue:CreateTable",
          "glue:UpdateTable",
          "glue:DeleteTable",
          "glue:BatchCreatePartition",
          "glue:BatchDeletePartition",
          "glue:UpdatePartition"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:aws:logs:*:*:/aws-glue/*"
      }
    ]
  })
}

# Glue Catalog Database
resource "aws_glue_catalog_database" "zero_etl_database" {
  name = "${local.name_prefix}_zero_etl_database"
}

# Glue Job for Zero-ETL
resource "aws_glue_job" "zero_etl_job" {
  name         = "${local.name_prefix}-dynamodb-to-s3-zero-etl"
  role_arn     = aws_iam_role.glue_zero_etl_role.arn
  glue_version = "4.0"

  command {
    script_location = "s3://${aws_s3_bucket.data_bucket.bucket}/scripts/glue-zero-etl-script.py"
    python_version  = "3"
  }

  default_arguments = {
    "--job-language"                     = "python"
    "--job-bookmark-option"              = "job-bookmark-enable"
    "--enable-continuous-cloudwatch-log" = "true"
    "--source_table"                     = aws_dynamodb_table.source_table.name
    "--target_bucket"                    = aws_s3_bucket.data_bucket.bucket
    "--database-name"                    = aws_glue_catalog_database.zero_etl_database.name
  }

  max_retries = 1
  timeout     = 30
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table"
  value       = aws_dynamodb_table.source_table.name
}

output "s3_bucket_name" {
  description = "Name of the S3 bucket"
  value       = aws_s3_bucket.data_bucket.bucket
}

output "glue_job_name" {
  description = "Name of the Glue job"
  value       = aws_glue_job.zero_etl_job.name
}

output "glue_database_name" {
  description = "Name of the Glue database"
  value       = aws_glue_catalog_database.zero_etl_database.name
}

output "iam_role_arn" {
  description = "ARN of the IAM role for Glue"
  value       = aws_iam_role.glue_zero_etl_role.arn
}

output "region" {
  description = "Current region"
  value       = var.aws_region
}

variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "table_name" {
  description = "DynamoDB table name"
  type        = string
  default     = "source-table"
}

variable "s3_bucket_name" {
  description = "S3 bucket name for data export"
  type        = string
  default     = "glue-zero-etl-bucket"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "dev"
}
